<?php
namespace App\Actions\ServiceOrders;use App\Domain\ServiceOrders\ServiceOrderStatusTransition;use App\Enums\{ServiceOrderStatus,TechnicianAssignmentStatus,TechnicianWorkingStatus};use App\Models\{ServiceOrder,Technician,ServiceOrderStatusHistory};use DomainException;use Illuminate\Support\Facades\DB;
class StartServiceOrder{public function execute(ServiceOrder $order,Technician $tech):ServiceOrder{return DB::transaction(function()use($order,$tech){$o=ServiceOrder::lockForUpdate()->findOrFail($order->id);app(ServiceOrderStatusTransition::class)->assertAllowed((string)$o->status,ServiceOrderStatus::IN_PROGRESS);$a=$o->assignments()->where('technician_id',$tech->id)->whereIn('status',[TechnicianAssignmentStatus::ASSIGNED,TechnicianAssignmentStatus::ACCEPTED])->latest()->first();if(!$a)throw new DomainException('Technician has no active assignment');$old=(string)$o->status;$a->update(['status'=>TechnicianAssignmentStatus::IN_PROGRESS,'started_at'=>now()]);$tech->update(['working_status'=>TechnicianWorkingStatus::BUSY]);$o->update(['status'=>ServiceOrderStatus::IN_PROGRESS,'started_at'=>$o->started_at?:now()]);ServiceOrderStatusHistory::create(['service_order_id'=>$o->id,'old_status'=>$old,'new_status'=>ServiceOrderStatus::IN_PROGRESS]);return $o->refresh();});}}
